preConditionHook:
// A bounded backward scan for the micro-channel breakout bar, and after it the failure
// of that break. For each candidate bar k the channel test is
// MicroChannelRunLength's all-pairs loop read at offset k + 1, so the deepest
// bar touched is low[maxWaitBars + minBars + 1].
// Both directions are evaluated on every candidate, matching EL's
// non-short-circuiting evaluation; every comparison is an ordinary EL
// relational and goes through el_lt/el_gt.
failedUp = false;
failedDn = false;
for (int k = 1; k <= (int)maxWaitBars; ++k) {
    chanLow = true;
    chanHigh = true;
    for (int j = k + 1; j <= k + (int)minBars; ++j) {
        if (el_lt(low[j], low[j + 1])) chanLow = false;
        if (el_gt(high[j], high[j + 1])) chanHigh = false;
    }
    if (chanLow && el_lt(low[k], low[k + 1]) && el_gt(close[0], high[k])) failedUp = true;
    if (chanHigh && el_gt(high[k], high[k + 1]) && el_lt(close[0], low[k])) failedDn = true;
}
